                post_hook={
                    "sql": "CREATE or replace TABLE maplemonk.shipment_status_mapping (SHIPPING_STATUS string(16777216),Mapped_Status string(16777216)); Insert INTO maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists maplemonk.facility_pincode (facility string,pincode string); create or replace table maplemonk.SAADAA_sales_consolidated_intermediate as select cast(b.customer_id as string) customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(coalesce(GA4.CHANNEL,b.FINAL_UTM_CHANNEL)) AS CHANNEL ,Upper(coalesce(GA4.final_source,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.tags ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(coalesce(c.productname,b.PRODUCT_NAME)) PRODUCT_NAME ,b.CURRENCY ,Upper(b.SHIPPING_CITY) As CITY ,Upper(b.SHIPPING_STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,GATEWAY PAYMENT_GATEWAY ,CASE WHEN EXISTS ( SELECT 1 FROM UNNEST(gateway) AS g WHERE LOWER(g) IN (\'cash on delivery (cod)\', \'cash on delivery\', \'cash_on_delivery\', \'cash\', \'manual\') ) THEN \'COD\' WHEN EXISTS ( SELECT 1 FROM UNNEST(gateway) AS g WHERE LOWER(g) IN (\'gokwik upi\', \'paytm\', \'paytm payment gateway\', \'razorpay secure\', \'gokwik cards\', \'gokwik netbanking\', \'razorpay_cards_upi_netbanking_wallets_\') ) THEN \'Prepaid\' ELSE \'Manual\' END AS payment_mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(coalesce(b.PRODUCT_NAME_FINAL,c.productname)) PRODUCT_NAME_FINAL ,UPPER(coalesce(b.PRODUCT_CATEGORY, c.category)) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,coalesce(case when b.commonsku =\'\' then null else b.commonsku end, c.master_sku) commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,upper(b.source_name) Source_name ,null Mapped_Source_Name ,coalesce(b.order_type,c.order_type) as Order_Type ,c.invoice_date ,case when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date), day) BETWEEN 0 and 6 then \'T-7\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date), day) BETWEEN 7 and 29 then \'T-7-30\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date), day) BETWEEN 30 and 44 then \'T-7-30-15\' end as week_type ,b.refund_date ,b.refund_value ,b.cancelled_at ,b.Gender ,b.Color_Family ,b.Product_Type ,b.Product_Variant ,b.FitType ,b.Sleeve_Type ,b.Neck_Collar_Type ,b.Size ,b.categoryType ,b.Garment_Length from maplemonk.SAADAA_SHOPIFY_FACT_ITEMS b left join ( select transactionid, final_source, channel from maplemonk.SAADAA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(b.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = replace(c.reference_code,\'#\',\'\') and replace(b.LINE_ITEM_ID,\'`\',\'\')=replace(c.Marketplace_LineItem_ID,\'`\',\'\') left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from maplemonk.SAADAA_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) UNION ALL SELECT cast(NULL as string) AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,cast(null as string) tags ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,cast(null as array<string>) AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,cast(null as string) AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,cast(NULL as date) AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(mapped_category) AS PRODUCT_CATEGORY ,UPPER(mapped_sub_category) AS PRODUCT_SUB_CATEGORY ,coalesce(case when b.commonsku =\'\' then null else b.commonsku end,b.master_SKU) commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,cast(null as string) Source_name ,cast(null as string) Mapped_Source_Name ,b.order_type Order_Type ,b.invoice_date ,case when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(ORDER_DATE) as date), day) BETWEEN 0 and 6 then \'T-7\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(ORDER_DATE) as date), day) BETWEEN 7 and 29 then \'T-7-30\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(ORDER_DATE) as date), day) BETWEEN 30 and 44 then \'T-7-30-15\' end as week_type ,null as refund_date ,null as refund_value ,null as cancelled_at ,b.Gender ,b.Color_Family ,b.Product_Type ,b.Product_Variant ,b.FitType ,b.Sleeve_Type ,b.Neck_Collar_Type ,b.Size ,b.categoryType ,b.Garment_Length FROM maplemonk.SAADAA_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\') ) union all SELECT cast(NULL AS string) customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, case when afi.shop_name = \'Amazon_FBA_Saada\' then \'AMAZON_FBA\' else \'AMAZON\' end AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, cast(null as string) tags, cast(null as string) AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS timestamp), CAST(UFI.shipping_last_update_date AS timestamp) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(afi.tax, 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, COALESCE(EEFI.awb, UFI.awb) AS AWB, cast(null as array<string>) AS Payment_Gateway, UPPER(COALESCE(EEFI.payment_mode, UFI.payment_mode)) AS Payment_Mode, UPPER(COALESCE(EEFI.Courier, UFI.courier)) AS COURIER, COALESCE(EEFI.manifest_date, UFI.dispatch_date) AS DISPATCH_DATE, COALESCE(EEFI.delivered_date , UFI.delivered_date ) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status, EEFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS INT64) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS INT64) END AS cancelled_quantity, cast(null as string) AS NEW_CUSTOMER_FLAG, cast(null as string) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, cast(null as date) AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID, EEFI.SKU) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(AFI.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, UPPER(AFI.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY, Coalesce(case when AFI.commonsku =\'\' then null else AFI.commonsku end, cast(AFI.commonsku as string)) commonsku, UPPER(EEFI.WAREHOUSE_NAME) AS WAREHOUSE, cast(eefi.pincode as string) as pincode, cast(pickup_pincode as string) pickup_pincode, cast(null as string) Source_name, cast(null as string) Mapped_Source_Name, afi.Order_Type Order_Type, coalesce(eefi.invoice_date) as Invoice_Date, case when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(afi.ORDER_TIMESTAMP) as date), day) BETWEEN 0 and 6 then \'T-7\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(afi.ORDER_TIMESTAMP) as date), day) BETWEEN 7 and 29 then \'T-7-30\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(TIMESTAMP(afi.ORDER_TIMESTAMP) as date), day) BETWEEN 30 and 44 then \'T-7-30-15\' end as week_type ,null as refund_date ,null as refund_value ,null as cancelled_at ,afi.Gender ,afi.Color_Family ,afi.Product_Type ,afi.Product_Variant ,afi.FitType ,afi.Sleeve_Type ,afi.Neck_Collar_Type ,afi.Size ,afi.categoryType ,afi.Garment_Length FROM maplemonk.SAADAA_AMAZON_FACT_ITEMS AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) EEFI ON AFI.Order_id = EEFI.reference_code AND AFI.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM maplemonk.SAADAA_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(AFI.order_id as string) = cast(UFI.order_id as string) AND cast(AFI.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) Union all select customer_id, Shop_name, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, cast(null as string) tags, PHONE, NAME, EMAIL, cast(SHIPPING_LAST_UPDATE_DATE as timestamp) SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, Product_Name, CURRENCY, CITY, State, Order_Status, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, Payment_Gateway, cast(Payment_Mode as string) payment_mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, cast(NEW_CUSTOMER_FLAG as string) as NEW_CUSTOMER_FLAG, cast(null as string) as ACQUISITION_PRODUCT, Days_in_Shipment, ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, pickup_pincode, Source_name, Mapped_Source_Name, Order_Type, invoice_date, case when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 0 and 6 then \'T-7\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 7 and 29 then \'T-7-30\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 30 and 44 then \'T-7-30-15\' end as week_type ,null as refund_date ,null as refund_value ,null as cancelled_at ,Gender ,Color_Family ,Product_Type ,Product_Variant ,FitType ,Sleeve_Type ,Neck_Collar_Type ,Size ,categoryType ,Garment_Length FROM saadaa-wh.MAPLEMONK.Saadaa_Store_Sales_Consolidated UNION ALL select cast(NULL AS string) customer_id, \'ZEPTO\' AS Shop_name, \'ZEPTO\' AS marketplace, \'ZEPTO\' AS CHANNEL, \'ZEPTO\' AS SOURCE, order_item as ORDER_ID, order_item AS reference_code, cast(null as string) tags, cast(NULL AS string) AS PHONE, cast(NULL AS string) as NAME, cast(NULL AS string) AS EMAIL, order_date AS SHIPPING_LAST_UPDATE_DATE, Sku_number as SKU, cast(SKU_NUMBER as string) PRODUCT_ID, Product_Name, \'INR\' as CURRENCY, City AS CITY, upper(State) AS STATE, \'COMPLETED\' AS Order_Status, cast(Order_Date as date) as Order_Date, CAST(Order_Date AS datetime) Order_Time, quantity, IFNULL(selling_price, 0) AS GROSS_SALES_BEFORE_TAX, cast(0 as float64) AS DISCOUNT, cast(0 as float64) as TAX, cast(0 as float64) as SHIPPING_PRICE, selling_price AS SELLING_PRICE, cast(null as string) AS OMS_order_status, \'COMPLETED\' AS SHIPPING_STATUS, \'COMPLETED\' AS FINAL_SHIPPING_STATUS, order_item AS SALEORDERITEMCODE, order_item AS SALES_ORDER_ITEM_ID, cast(null as string) AS AWB, cast(null as array<string>) AS Payment_Gateway, cast(null as string) AS Payment_Mode, cast(null as string) AS COURIER, cast(null as datetime) AS DISPATCH_DATE, cast(order_date as datetime) AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, cast(null as INT64) AS RETURN_FLAG, cast(null as FLOAT64) AS returned_quantity, cast(null as FLOAT64) AS returned_sales, cast(null as INT64) AS cancelled_quantity, cast(NULL as string) AS NEW_CUSTOMER_FLAG, cast(NULL as string) AS ACQUISITION_PRODUCT, cast(null as INT64) AS Days_in_Shipment, cast(NULL as date) AS ACQUISITION_DATE, SKU_NUMBER AS SKU_CODE, PRODUCT_NAME_FINAL, final_product_category AS PRODUCT_CATEGORY, sub_category AS PRODUCT_SUB_CATEGORY, commonsku as commonsku, cast(null as string) AS WAREHOUSE, pincode, cast(null as string) pickup_pincode, cast(null as string) Source_name, cast(null as string) Mapped_Source_Name, cast(null as string) Order_Type, Order_Date as Invoice_Date, case when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 0 and 6 then \'T-7\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 7 and 29 then \'T-7-30\' when date_diff(date(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY)), cast(Order_Date as date), day) BETWEEN 30 and 44 then \'T-7-30-15\' end as week_type ,null as refund_date ,null as refund_value ,null as cancelled_at ,Gender ,Color_Family ,Product_Type ,Product_Variant ,FitType ,Sleeve_Type ,Neck_Collar_Type ,Size ,categoryType ,Garment_Length FROM saadaa-wh.maplemonk.saadaa_zepto_fact_items ; CREATE OR REPLACE TABLE maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + dense_rank() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone phone FROM maplemonk.SAADAA_sales_consolidated_intermediate where phone is not null ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, coalesce(p.maple_monk_id,pe.maple_monk_id) maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.SAADAA_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN (select * from new_phone_numbers qualify row_number() over (partition by lower(email) order by 1) = 1) pe ON lower(pe.email) = lower(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.SAADAA_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case when (abs(selling_price) > 10 AND (order_type is null or not(order_type in (\'Test Order\',\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\',\'Return Prime Order\')))) then \'Gross Sale Orders\' else \'Gross Orders\' end as GROSS_ORDER_TYPE, CASE WHEN m.pincode LIKE \'1%\' OR m.pincode LIKE \'2%\' THEN \'North Region\' WHEN m.pincode LIKE \'3%\' OR m.pincode LIKE \'4%\' THEN \'West Region\' WHEN m.pincode LIKE \'5%\' OR m.pincode LIKE \'6%\' THEN \'South Region\' WHEN m.pincode LIKE \'7%\' OR m.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region, iso.iso_code as state_iso_code, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.SAADAA_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN (select * from maplemonk.GS_State_ISO) iso ON lower(replace(iso.state,\' \',\'\')) = lower(replace(m.state,\' \',\'\')) ; ALTER TABLE maplemonk.SAADAA_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.SAADAA_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.SAADAA_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.SAADAA_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.SAADAA_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.SAADAA_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.SAADAA_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.SAADAA_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.SAADAA_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.SAADAA_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.SAADAA_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM maplemonk.SAADAA_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.SAADAA_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE maplemonk.SAADAA_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'\"MAHARASTRA, THANE\"\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\',\'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\',\'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\',\'\') THEN NULL ELSE state END WHERE TRUE; create or replace table maplemonk.saadaa_sales_consolidated as select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, tags, GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, payment_mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, Source_name, Mapped_Source_Name, Order_Type, invoice_date, week_type, refund_date, refund_value, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, null as shopify_refund_value, null as return_tax, cancelled_at ,Gender ,Color_Family ,Product_Type ,Product_Variant ,FitType ,Sleeve_Type ,Neck_Collar_Type ,Size ,categoryType ,Garment_Length ,state_iso_code from maplemonk.saadaa_sales_consolidated union all (select null as customer_id_final, null as acquisition_date, null as first_complete_order_date, null as Order_Quantity, null as tags, case when (abs(refund_value) > 10 AND (order_type is null or not(order_type in (\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\')))) then \'Gross Sale Orders\' else \'Gross Orders\' end as GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, null as ORDER_ID, null as reference_code, null as PHONE, null as NAME, null as EMAIL, null as SHIPPING_LAST_UPDATE_DATE, null as SKU, null as PRODUCT_ID, null as PRODUCT_NAME, null as CURRENCY, CITY, State, null as ORDER_STATUS, refund_date as Order_Date, null as Order_Time, null as QUANTITY, null as GROSS_SALES_BEFORE_TAX, null as DISCOUNT, null as TAX, null as SHIPPING_PRICE, null as SELLING_PRICE, null as OMS_order_status, null as SHIPPING_STATUS, null as FINAL_SHIPPING_STATUS, null as SALEORDERITEMCODE, null as SALES_ORDER_ITEM_ID, null as AWB, null as PAYMENT_GATEWAY, null as payment_mode, null as COURIER, null as DISPATCH_DATE, null as DELIVERED_DATE, null as DELIVERED_STATUS, null as RETURN_FLAG, null as returned_quantity, null as returned_sales, null as cancelled_quantity, null as Days_in_Shipment, null as MARKETPLACE_ACQUISITION_DATE, null as SKU_CODE, null as PRODUCT_NAME_FINAL, null as PRODUCT_CATEGORY, null as PRODUCT_SUB_CATEGORY, null as commonsku, null as WAREHOUSE, null as pincode, null as source_pincode, null as Source_name, null as Mapped_Source_Name, Order_Type, null as invoice_date, null as week_type, refund_date, refund_value, null as new_customer_flag, null as new_customer_flag_month, null as acquisition_product, null as acquisition_channel, null as acquisition_marketplace, refund_value as shopify_refund_value, tax as return_tax, null as cancelled_at, null Gender, null Color_Family, null Product_Type, null Product_Variant, null FitType, null Sleeve_Type, null Neck_Collar_Type, null Size, null categoryType, null Garment_Length, state_iso_code from maplemonk.saadaa_sales_consolidated where (lower(marketplace) like \'%shopify%\' or lower(marketplace) like \'%website%\') and ifnull(refund_value,0) > 0 ) ; CREATE OR REPLACE TABLE maplemonk.saadaa_marketplace_pincode_analysis AS WITH pincode AS ( SELECT pincode, city, state, s.order_date, SUM(selling_price) AS pincode_sales, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN order_id END) AS Shopify_Orders, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN order_id END) AS Amazon_Orders, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN order_id END) AS Myntra_Orders, sum(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN quantity END) AS Shopify_Order_Quantity, sum(CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN quantity END) AS Amazon_Order_Quantity, sum(CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN quantity END) AS Myntra_Order_Quantity, sum(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN selling_price END) AS Shopify_Sales, sum(CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN selling_price END) AS Amazon_Sales, sum(CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN selling_price END) AS Myntra_Sales, COUNT(DISTINCT order_id) AS Total_Orders, sum(ifnull(quantity,0)) as Total_Order_Quantity, sum(ifnull(selling_price,0)) as Total_Sales, SAFE_DIVIDE( COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN order_id END), COUNT(DISTINCT order_id) ) AS D2C_Percentage_orders, SAFE_DIVIDE( sum(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN ifnull(quantity,0) END), sum(ifnull(quantity,0)) ) AS D2C_Percentage_order_quantity, SAFE_DIVIDE( sum(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN selling_price END), sum(ifnull(selling_price,0)) ) AS D2C_Percentage_Sales FROM saadaa-wh.MAPLEMONK.SAADAA_sales_consolidated s LEFT JOIN ( SELECT order_date, SUM(selling_price) AS daily_sales FROM saadaa-wh.MAPLEMONK.SAADAA_sales_consolidated WHERE GROSS_ORDER_TYPE = \'Gross Sale Orders\' GROUP BY order_date ) e ON e.order_date = s.order_date WHERE GROSS_ORDER_TYPE = \'Gross Sale Orders\' GROUP BY 1, 2, 3, 4 ) SELECT p.*, p1.Shopify_Orders AS Shopify_Order_last_year, p1.Amazon_Orders AS Amazon_Order_last_year, p1.Myntra_Orders AS Myntra_Order_last_year, p1.Shopify_Order_Quantity AS Shopify_Order_Quantity_last_year, p1.Amazon_Order_Quantity AS Amazon_Order_Quantity_last_year, p1.Myntra_Order_Quantity AS Myntra_Order_Quantity_last_year, p1.Shopify_Sales AS Shopify_Sales_last_year, p1.Amazon_Sales AS Amazon_Sales_last_year, p1.Myntra_Sales AS Myntra_Sales_last_year, p1.Total_Orders AS Total_order_last_year, p1.Total_Order_Quantity AS Total_order_quantity_last_year, p1.Total_Sales AS Total_sales_last_year, p1.D2C_Percentage_orders AS D2C_Percentage_orders_last_year, p1.D2C_Percentage_order_quantity AS D2C_Percentage_order_quantity_last_year, p1.D2C_Percentage_sales AS D2C_Percentage_sales_last_year, p2.Shopify_Orders AS Shopify_Orders_last_month, p2.Shopify_Order_Quantity AS Shopify_Order_Quantity_last_month, p2.Shopify_Sales AS Shopify_Sales_last_month, p2.Total_Sales AS Total_Sales_last_month, p2.Total_Orders AS Total_Orders_last_month, p2.Total_Order_Quantity AS Total_Order_Quantity_last_month, SAFE_DIVIDE((p1.D2C_Percentage_orders - p.D2C_Percentage_orders), p.D2C_Percentage_orders) AS Rate_of_Change_of_D2C_percentage_orders_last_year, SAFE_DIVIDE((p1.D2C_Percentage_order_quantity - p.D2C_Percentage_order_quantity), p.D2C_Percentage_order_quantity) AS Rate_of_Change_of_D2C_percentage_order_quantity_last_year, SAFE_DIVIDE((p1.D2C_Percentage_sales - p.D2C_Percentage_sales), p.D2C_Percentage_sales) AS Rate_of_Change_of_D2C_percentage__sales_last_year, SUM(p.pincode_sales) OVER (PARTITION BY p.state, p.order_date) AS state_daily_sales, SUM(p.pincode_sales) OVER (PARTITION BY p.order_date) AS total_daily_sales FROM pincode p LEFT JOIN (SELECT * FROM pincode QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode, order_date ORDER BY order_date DESC) = 1) p1 ON DATE_SUB(p.order_date, INTERVAL 1 YEAR) = p1.order_date AND p.pincode = p1.pincode LEFT JOIN (SELECT * FROM pincode QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode, order_date ORDER BY order_date DESC) = 1) p2 ON DATE_SUB(p.order_date, INTERVAL 1 MONTH) = p2.order_date AND p.pincode = p2.pincode ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

